<?php
if ( ! defined( 'ABSPATH' ) ) { exit; }

class Design_Core_Elementor_Rest_Controller {
    public function register_routes() {
        $routes = array('/capabilities'=>'get_capabilities','/components'=>'get_components','/sections'=>'get_sections','/widgets'=>'get_widgets','/tokens'=>'get_tokens','/search'=>'search_registry','/diagnostics'=>'get_diagnostics','/readiness'=>'get_readiness','/conversions'=>'get_conversions','/evidence'=>'get_evidence');
        foreach($routes as $route=>$callback){register_rest_route('design-core-elementor/v1',$route,array('methods'=>WP_REST_Server::READABLE,'callback'=>array($this,$callback),'permission_callback'=>array($this,'can_manage'),'args'=>'/search'===$route?array('q'=>array('sanitize_callback'=>'sanitize_text_field')):array()));}
        register_rest_route('design-core-elementor/v1','/elementor-widgets',array('methods'=>WP_REST_Server::READABLE,'callback'=>array($this,'get_elementor_widgets'),'permission_callback'=>array($this,'can_manage'),'args'=>array('source'=>array('sanitize_callback'=>'sanitize_key','default'=>'all'),'q'=>array('sanitize_callback'=>'sanitize_text_field','default'=>''))));
        register_rest_route('design-core-elementor/v1','/elementor-widgets/(?P<widget>[a-zA-Z0-9_-]+)',array('methods'=>WP_REST_Server::READABLE,'callback'=>array($this,'get_elementor_widget'),'permission_callback'=>array($this,'can_manage'),'args'=>array('widget'=>array('sanitize_callback'=>'sanitize_key','required'=>true))));
        register_rest_route('design-core-elementor/v1','/elementor-widget-candidates',array('methods'=>WP_REST_Server::READABLE,'callback'=>array($this,'get_elementor_widget_candidates'),'permission_callback'=>array($this,'can_manage'),'args'=>array('intent'=>array('sanitize_callback'=>'sanitize_key','default'=>''),'controls'=>array('sanitize_callback'=>'sanitize_text_field','default'=>''),'capabilities'=>array('sanitize_callback'=>'sanitize_text_field','default'=>''),'keywords'=>array('sanitize_callback'=>'sanitize_text_field','default'=>''),'limit'=>array('sanitize_callback'=>'absint','default'=>10))));
        register_rest_route('design-core-elementor/v1','/build-preview',array('methods'=>WP_REST_Server::CREATABLE,'callback'=>array($this,'post_build_preview'),'permission_callback'=>array($this,'can_manage')));
        register_rest_route('design-core-elementor/v1','/page-snapshot/(?P<id>\d+)',array('methods'=>WP_REST_Server::READABLE,'callback'=>array($this,'get_page_snapshot'),'permission_callback'=>array($this,'can_manage'),'args'=>array('id'=>array('sanitize_callback'=>'absint','required'=>true))));
        register_rest_route('design-core-elementor/v1','/history',array('methods'=>WP_REST_Server::READABLE,'callback'=>array($this,'get_history'),'permission_callback'=>array($this,'can_manage')));
        register_rest_route('design-core-elementor/v1','/history/(?P<entry>[a-zA-Z0-9_-]+)/rollback',array('methods'=>WP_REST_Server::CREATABLE,'callback'=>array($this,'post_history_rollback'),'permission_callback'=>array($this,'can_manage'),'args'=>array('entry'=>array('sanitize_callback'=>'sanitize_key','required'=>true))));
        register_rest_route('design-core-elementor/v1','/figma/design-ir',array('methods'=>WP_REST_Server::CREATABLE,'callback'=>array($this,'post_figma_design_ir'),'permission_callback'=>array($this,'can_manage')));
        register_rest_route('design-core-elementor/v1','/visual-feedback',array('methods'=>WP_REST_Server::CREATABLE,'callback'=>array($this,'post_visual_feedback'),'permission_callback'=>array($this,'can_manage')));
        register_rest_route('design-core-elementor/v1','/visual-correction',array('methods'=>WP_REST_Server::CREATABLE,'callback'=>array($this,'post_visual_correction'),'permission_callback'=>array($this,'can_manage')));
        register_rest_route('design-core-elementor/v1','/benchmarks',array('methods'=>WP_REST_Server::READABLE,'callback'=>array($this,'get_benchmarks'),'permission_callback'=>array($this,'can_manage')));
        register_rest_route('design-core-elementor/v1','/benchmarks/(?P<id>[a-zA-Z0-9_-]+)/planning',array('methods'=>WP_REST_Server::READABLE,'callback'=>array($this,'get_benchmark_planning'),'permission_callback'=>array($this,'can_manage'),'args'=>array('id'=>array('sanitize_callback'=>'sanitize_key','required'=>true))));
        register_rest_route('design-core-elementor/v1','/page-shell/compile',array('methods'=>WP_REST_Server::CREATABLE,'callback'=>array($this,'post_page_shell_compile'),'permission_callback'=>array($this,'can_manage')));
        register_rest_route('design-core-elementor/v1','/section-explain/(?P<master>[a-zA-Z0-9_-]+)',array('methods'=>WP_REST_Server::READABLE,'callback'=>array($this,'get_section_explain'),'permission_callback'=>array($this,'can_manage'),'args'=>array('master'=>array('sanitize_callback'=>'sanitize_text_field','required'=>true))));
        register_rest_route('design-core-elementor/v1','/section-explain',array('methods'=>WP_REST_Server::CREATABLE,'callback'=>array($this,'post_section_explain'),'permission_callback'=>array($this,'can_manage')));
        register_rest_route('design-core-elementor/v1','/agent/tools',array('methods'=>WP_REST_Server::READABLE,'callback'=>array($this,'get_agent_tools'),'permission_callback'=>array($this,'can_manage'),'args'=>array('q'=>array('sanitize_callback'=>'sanitize_text_field','default'=>''))));
        register_rest_route('design-core-elementor/v1','/agent/tools/(?P<tool>[a-zA-Z0-9_-]+)/schema',array('methods'=>WP_REST_Server::READABLE,'callback'=>array($this,'get_agent_tool_schema'),'permission_callback'=>array($this,'can_manage'),'args'=>array('tool'=>array('sanitize_callback'=>'sanitize_key','required'=>true))));
        register_rest_route('design-core-elementor/v1','/agent/execute',array('methods'=>WP_REST_Server::CREATABLE,'callback'=>array($this,'post_agent_execute'),'permission_callback'=>array($this,'can_manage')));
